"use client";

import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import { createClient } from "@supabase/supabase-js";


const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
  {
    auth: {
      persistSession: true,
      autoRefreshToken: true,
      detectSessionInUrl: true,
    },
  }
);

const SERVING = "data:image/jpeg;base64,";
const LOGO = "data:image/jpeg;base64,";

type Category = {
  id: string;
  name: string;
  sort_order: number;
};

type MenuItem = {
  id: string;
  category_id: string | null;
  name: string;
  description: string | null;
  price: number | null;
  featured: boolean;
  sort_order: number;
};

type Restaurant = {
  id: string;
  name: string;
  slug: string;
  phone: string | null;
  address_line_1: string | null;
  city: string | null;
  state: string | null;
  zip: string | null;
  published: boolean;
};

type Ordering = {
  online_ordering_url: string | null;
};

const copy = {
  en: {
    nav: ["HOME","OUR STORY","MENU","CATERING","ORDER ONLINE","LOCATIONS","CONTACT"],
    language: "🇭🇳 Español",
    eyebrow: "VI POLLOS MENU",
    title: "AUTHENTIC HONDURAN FLAVOR",
    subtitle: "Fresh food, family recipes, and generous plates made with pride.",
    order: "ORDER ONLINE",
    loading: "Loading menu...",
    unavailable: "SOLD OUT",
    featured: "FEATURED",
    note: "Menu items and prices are updated directly by Vi Pollos.",
    empty: "No menu items are currently available in this category.",
    footer: "© 2026 Vi Pollos. All rights reserved."
  },
  es: {
    nav: ["INICIO","NUESTRA HISTORIA","MENÚ","CATERING","ORDENAR","UBICACIONES","CONTACTO"],
    language: "🇺🇸 English",
    eyebrow: "MENÚ DE VI POLLOS",
    title: "AUTÉNTICO SABOR HONDUREÑO",
    subtitle: "Comida fresca, recetas familiares y platos generosos hechos con orgullo.",
    order: "ORDENAR",
    loading: "Cargando menú...",
    unavailable: "AGOTADO",
    featured: "DESTACADO",
    note: "Los artículos y precios del menú son actualizados directamente por Vi Pollos.",
    empty: "No hay artículos disponibles actualmente en esta categoría.",
    footer: "© 2026 Vi Pollos. Todos los derechos reservados."
  }
};

function ViPollosFoodMenuPage() {
  const params = useParams<{ slug: string }>();
  const slug = Array.isArray(params?.slug) ? params.slug[0] : params?.slug;

  const [lang, setLang] = useState<"en" | "es">("en");
  const [restaurant, setRestaurant] = useState<Restaurant | null>(null);
  const [ordering, setOrdering] = useState<Ordering | null>(null);
  const [categories, setCategories] = useState<Category[]>([]);
  const [items, setItems] = useState<MenuItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const t = copy[lang];

  useEffect(() => {
    if (!slug) return;
    loadMenu();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [slug]);

  async function loadMenu() {
    if (!slug) return;

    setLoading(true);
    setError("");

    const {
      data: { session },
    } = await supabase.auth.getSession();

    const response = await fetch(
      `/api/public/menu?slug=${encodeURIComponent(slug)}`,
      {
        headers: session?.access_token
          ? { Authorization: `Bearer ${session.access_token}` }
          : {},
      }
    );

    const data = await response.json();

    if (!response.ok) {
      setError(data.error || "Unable to load the Vi Pollos menu.");
      setLoading(false);
      return;
    }

    setRestaurant(data.restaurant || null);
    setOrdering(data.ordering || null);
    setCategories((data.categories || []) as Category[]);
    setItems((data.items || []) as MenuItem[]);
    setLoading(false);
  }

  function categoryName(category: Category) {
    return category.name;
  }

  function itemName(item: MenuItem) {
    return item.name;
  }

  function itemDescription(item: MenuItem) {
    return item.description;
  }

  function formatPrice(price: number | null) {
    if (price === null || price === undefined) return "";
    return `$${Number(price).toFixed(2)}`;
  }

  const orderUrl =
    ordering?.online_ordering_url ||
    "https://www.doordash.com/store/vi-pollos-clayton-41942251/";

  const addressLine = restaurant?.address_line_1 || "8928 Clayton Blvd";
  const cityStateZip = [
    restaurant?.city || "Clayton",
    restaurant?.state || "NC",
    restaurant?.zip || "27520",
  ]
    .filter(Boolean)
    .join(", ");

  const phone = restaurant?.phone || "9198798000";

  return (
    <main className="page">
      <style jsx global>{`
        * { box-sizing:border-box; }
        html,body { margin:0; padding:0; background:#061a31; font-family:Arial,Helvetica,sans-serif; }
        a { color:inherit; text-decoration:none; }
        button { font:inherit; }
      `}</style>

      <style jsx>{`
        .page { min-height:100vh; background:#061a31; color:white; }
        .site { max-width:1440px; margin:0 auto; background:#f3eadb; box-shadow:0 0 70px rgba(0,0,0,.45); }

        .header {
          height:104px; background:#050505; display:flex; align-items:center;
          padding:0 58px; gap:28px; position:relative; z-index:10;
        }
        .logo { width:235px; height:92px; object-fit:contain; object-position:left center; }
        .nav { margin-left:auto; display:flex; align-items:center; gap:25px; font-size:12px; font-weight:900; }
        .nav a:nth-child(3) { color:#d8aa22; border-bottom:2px solid #d8aa22; padding-bottom:9px; }
        .orderTop { background:#075cb3; padding:14px 24px; font-weight:900; }
        .lang { border:1px solid rgba(255,255,255,.35); background:#111; color:white; padding:12px 16px; cursor:pointer; border-radius:3px; font-weight:800; }

        .hero { display:grid; grid-template-columns:1fr .86fr; min-height:380px; background:#050505; overflow:hidden; }
        .heroText { padding:58px; display:flex; flex-direction:column; justify-content:center; }
        .eyebrow { color:#d7a51f; font-size:12px; font-weight:900; letter-spacing:1.4px; margin-bottom:13px; }
        .hero h1 { font-family:Georgia,"Times New Roman",serif; font-size:54px; line-height:1.02; margin:0; max-width:650px; }
        .hero h1 span { display:block; color:#0b59ad; font-family:Arial,Helvetica,sans-serif; font-size:.48em; letter-spacing:1px; margin-top:13px; }
        .hero p { max-width:560px; color:#ececec; font-size:16px; line-height:1.6; margin:20px 0 24px; }
        .heroPhoto { width:100%; height:100%; object-fit:cover; object-position:center 40%; }
        .heroActions { display:flex; gap:12px; }
        .blueBtn,.outlineBtn { padding:13px 20px; font-weight:900; font-size:12px; }
        .blueBtn { background:#075cb3; }
        .outlineBtn { border:1px solid white; }

        .categoryBar {
          background:#073664; display:flex; justify-content:center; flex-wrap:wrap;
          gap:10px; padding:18px 24px; border-top:3px solid #b78924; border-bottom:3px solid #b78924;
          position:sticky; top:0; z-index:7;
        }
        .categoryBar a {
          border:1px solid rgba(255,255,255,.26); padding:9px 14px; border-radius:3px;
          font-size:11px; font-weight:900; letter-spacing:.3px;
        }

        .menuWrap { padding:42px 56px 62px; color:#092d55; }
        .note { max-width:760px; margin:0 auto 28px; text-align:center; color:#71695f; font-size:12px; }
        .message {
          max-width:760px; margin:40px auto; background:#fffaf2; border:1px solid #dacdb9;
          padding:24px; border-radius:8px; text-align:center; color:#233c55;
        }

        .section {
          scroll-margin-top:88px; margin-bottom:26px; background:#fffaf2;
          border:1px solid rgba(9,45,85,.12); border-radius:10px; overflow:hidden;
          box-shadow:0 6px 18px rgba(0,0,0,.05);
        }
        .sectionHeader {
          background:#0b355f; color:white; padding:17px 22px; display:flex; align-items:center; gap:12px;
          border-bottom:3px solid #b78924;
        }
        .sectionHeader h2 { margin:0; font-family:Georgia,serif; font-size:24px; }
        .sectionCount { margin-left:auto; color:#bfd0e1; font-size:10px; font-weight:900; }

        .items { display:grid; grid-template-columns:1fr 1fr; }
        .item {
          padding:22px 24px; border-bottom:1px solid #eadfce; min-height:154px;
        }
        .item:nth-child(odd) { border-right:1px solid #eadfce; }
        .itemTop { display:flex; align-items:flex-start; gap:14px; }
        .itemName { font-size:17px; font-weight:900; color:#143656; line-height:1.25; }
        .price { margin-left:auto; font-size:18px; font-weight:900; color:#0b579e; white-space:nowrap; }
        .badges { display:flex; gap:7px; margin-top:8px; flex-wrap:wrap; }
        .badge { display:inline-flex; padding:4px 7px; border-radius:999px; font-size:9px; font-weight:900; letter-spacing:.5px; }
        .featured { background:#fff0bf; color:#835d00; }
        .soldout { background:#f6d9d5; color:#9a2a20; }
        .desc { margin:10px 0 0; color:#5e6871; font-size:13px; line-height:1.6; max-width:92%; }

        .cta {
          background:linear-gradient(135deg,#11100f,#251a11); color:white; padding:38px;
          border-radius:9px; display:flex; align-items:center; gap:28px; border-top:3px solid #b78924;
          margin-top:34px;
        }
        .ctaText { flex:1; }
        .cta h3 { margin:0 0 8px; font-family:Georgia,serif; font-size:28px; }
        .cta p { margin:0; color:#e5e5e5; font-size:13px; line-height:1.5; }

        .footer { background:#06294d; color:#dce4ec; text-align:center; padding:15px 20px; font-size:10px; }

        @media(max-width:1050px) {
          .nav { display:none; }
          .header { padding:0 28px; }
          .orderTop { margin-left:auto; }
          .hero { grid-template-columns:1fr; }
          .heroPhoto { height:340px; }
        }
        @media(max-width:760px) {
          .header { height:84px; padding:0 16px; gap:10px; }
          .logo { width:145px; height:70px; }
          .orderTop { padding:10px 12px; font-size:10px; }
          .lang { padding:9px 10px; font-size:10px; }
          .heroText { padding:38px 24px; }
          .hero h1 { font-size:40px; }
          .heroPhoto { height:280px; }
          .categoryBar { justify-content:flex-start; overflow-x:auto; flex-wrap:nowrap; }
          .categoryBar a { white-space:nowrap; }
          .menuWrap { padding:30px 16px 46px; }
          .items { grid-template-columns:1fr; }
          .item:nth-child(odd) { border-right:none; }
          .cta { flex-direction:column; align-items:flex-start; }
        }
      `}</style>

      <div className="site">
        {restaurant && !restaurant.published && (
          <div
            style={{
              position: "fixed",
              right: 14,
              bottom: 14,
              zIndex: 1000,
              background: "#d8aa22",
              color: "#061a31",
              padding: "8px 11px",
              borderRadius: 4,
              fontSize: 10,
              fontWeight: 900,
              letterSpacing: 1,
              boxShadow: "0 6px 20px rgba(0,0,0,.25)",
            }}
          >
            RESTAURANT OS PREVIEW
          </div>
        )}
        <header className="header">
          <a href={`/r/${slug}`}><img src={LOGO} alt="Vi Pollos" className="logo" /></a>
          <nav className="nav">
            <a href={`/r/${slug}`}>{t.nav[0]}</a>
            <a href={`/r/${slug}#story`}>{t.nav[1]}</a>
            <a href={`/r/${slug}/food-menu`}>{t.nav[2]}</a>
            <a href={`/r/${slug}#catering`}>{t.nav[3]}</a>
            <a href={orderUrl} target="_blank" rel="noreferrer">{t.nav[4]}</a>
            <a href={`/r/${slug}#visit`}>{t.nav[5]}</a>
            <a href={`/r/${slug}#visit`}>{t.nav[6]}</a>
          </nav>
          <a className="orderTop" href={orderUrl} target="_blank" rel="noreferrer">{t.order}</a>
          <button className="lang" onClick={() => setLang(lang === "en" ? "es" : "en")}>{t.language}</button>
        </header>

        <section className="hero">
          <div className="heroText">
            <div className="eyebrow">{t.eyebrow}</div>
            <h1>{t.title}<span>MADE WITH PRIDE. SERVED WITH HEART.</span></h1>
            <p>{t.subtitle}</p>
            <div className="heroActions">
              <a className="blueBtn" href={orderUrl} target="_blank" rel="noreferrer">{t.order}</a>
              <a className="outlineBtn" href="#menu">VIEW MENU ↓</a>
            </div>
          </div>
          <img src={SERVING} alt="Vi Pollos food" className="heroPhoto" />
        </section>

        <div className="categoryBar">
          {categories.map((category) => (
            <a key={category.id} href={`#cat-${category.id}`}>{categoryName(category)}</a>
          ))}
        </div>

        <section className="menuWrap" id="menu">
          <div className="note">{t.note}</div>

          {loading && <div className="message">{t.loading}</div>}
          {error && <div className="message">{error}</div>}

          {!loading && !error && categories.map((category) => {
            const categoryItems = items.filter((item) => item.category_id === category.id);
            return (
              <section className="section" id={`cat-${category.id}`} key={category.id}>
                <div className="sectionHeader">
                  <h2>{categoryName(category)}</h2>
                  <span className="sectionCount">{categoryItems.length} ITEMS</span>
                </div>

                {categoryItems.length === 0 ? (
                  <div className="message">{t.empty}</div>
                ) : (
                  <div className="items">
                    {categoryItems.map((item) => (
                      <article className="item" key={item.id}>
                        <div className="itemTop">
                          <div>
                            <div className="itemName">{itemName(item)}</div>
                            <div className="badges">
                              {item.featured && <span className="badge featured">{t.featured}</span>}
                              
                            </div>
                          </div>
                          <div className="price">{formatPrice(item.price)}</div>
                        </div>
                        {itemDescription(item) && <p className="desc">{itemDescription(item)}</p>}
                      </article>
                    ))}
                  </div>
                )}
              </section>
            );
          })}

          <section className="cta">
            <div className="ctaText">
              <div className="eyebrow">READY TO EAT?</div>
              <h3>Order Vi Pollos Online</h3>
              <p>Pickup and delivery are available through the current online ordering menu.</p>
            </div>
            <a className="blueBtn" href={orderUrl} target="_blank" rel="noreferrer">{t.order}</a>
          </section>
        </section>

        <footer className="footer">{t.footer} &nbsp;&nbsp; • &nbsp;&nbsp; {addressLine}, {cityStateZip} &nbsp;&nbsp; • &nbsp;&nbsp; {phone}</footer>
      </div>
    </main>
  );
}


function StandardFoodMenuPage({ slug, themeKey }: { slug: string; themeKey: string | null }) {
  const [restaurant, setRestaurant] = useState<any>(null);
  const [categories, setCategories] = useState<any[]>([]);
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const palette = (() => {
    switch (themeKey) {
      case "mex-jefe-bold":
        return { bg:"#F5E6C8", surface:"#FFF4DD", nav:"#0A0A0A", accent:"#E43A2F", accent2:"#F4C443", text:"#101010", muted:"#6B5A45" };
      case "mex-cantina-social":
        return { bg:"#F3E4C9", surface:"#FFF5E4", nav:"#163D36", accent:"#E15B4D", accent2:"#F0D6A8", text:"#17352F", muted:"#6B756F" };
      case "mex-coastal-taco":
        return { bg:"#F7F4EE", surface:"#FFFFFF", nav:"#6B9C92", accent:"#E39A64", accent2:"#F0D9BF", text:"#213831", muted:"#718079" };
      case "mex-cosmic-night":
        return { bg:"#09090D", surface:"#15151D", nav:"#08080B", accent:"#A72D68", accent2:"#DDBB63", text:"#F6F1E7", muted:"#AAA4AA" };
      case "mex-birria-street":
        return { bg:"#170B08", surface:"#2A130D", nav:"#120805", accent:"#D83D22", accent2:"#F49A2C", text:"#FFF4EA", muted:"#D9BFB4" };
      case "pizza-italian":
        return { bg:"#F3E8D5", surface:"#FFF9EF", nav:"#1B2D22", accent:"#9D2F27", accent2:"#D8B98B", text:"#1E201A", muted:"#665F53" };
      case "bbq-smokehouse":
        return { bg:"#1D1713", surface:"#2A211B", nav:"#0D0B09", accent:"#C85C2D", accent2:"#D7A45F", text:"#F2E4CE", muted:"#C8B69E" };
      case "cafe-bakery":
        return { bg:"#F4EFE8", surface:"#FFFDF9", nav:"#6B4F3A", accent:"#9A6D4B", accent2:"#C7A57C", text:"#4A392F", muted:"#7C6C61" };
      case "upscale-dining":
        return { bg:"#0C0C0C", surface:"#151515", nav:"#080808", accent:"#C6A35B", accent2:"#E4D2A3", text:"#F4F0E8", muted:"#B9B3A9" };
      default:
        return { bg:"#F7F1E8", surface:"#FFFFFF", nav:"#0B2037", accent:"#0B5F9F", accent2:"#F4B400", text:"#0F2740", muted:"#607284" };
    }
  })();

  useEffect(() => {
    async function load() {
      setLoading(true);
      setError("");

      const response = await fetch(`/api/public/menu?slug=${encodeURIComponent(slug)}`);
      const data = await response.json();

      if (!response.ok) {
        setError(data.error || "Unable to load menu.");
        setLoading(false);
        return;
      }

      setRestaurant(data.restaurant || null);
      setCategories(data.categories || []);
      setItems(data.items || []);
      setLoading(false);
    }

    load();
  }, [slug]);

  if (loading) {
    return <main style={{minHeight:"100vh",background:"#08111f",color:"#fff",display:"grid",placeItems:"center",fontFamily:"Arial"}}>Loading menu...</main>;
  }

  if (error || !restaurant) {
    return <main style={{minHeight:"100vh",background:"#08111f",color:"#fff",display:"grid",placeItems:"center",fontFamily:"Arial"}}>{error || "Menu unavailable."}</main>;
  }

  const grouped = categories.map((category:any) => ({
    ...category,
    items: items.filter((item:any) => item.category_id === category.id),
  }));

  return (
    <main style={{minHeight:"100vh",background:palette.bg,color:palette.text,fontFamily:"Arial,Helvetica,sans-serif"}}>
      <header style={{background:palette.nav,color:"#fff"}}>
        <div style={{maxWidth:1200,margin:"0 auto",padding:"20px 24px",display:"flex",alignItems:"center",gap:20}}>
          <a href={`/r/${slug}`} style={{fontSize:22,fontWeight:900,textDecoration:"none",color:"#fff"}}>
            {restaurant.name}
          </a>
          <nav style={{marginLeft:"auto",display:"flex",gap:18,fontSize:11,fontWeight:900}}>
            <a href={`/r/${slug}`} style={{color:"#fff",textDecoration:"none"}}>HOME</a>
            <a href={`/r/${slug}/food-menu`} style={{color:palette.accent2,textDecoration:"none"}}>MENU</a>
            <a href={`/r/${slug}/offers`} style={{color:"#fff",textDecoration:"none"}}>OFFERS</a>
            <a href={`/r/${slug}/vip`} style={{color:"#fff",textDecoration:"none"}}>VIP</a>
          </nav>
        </div>
      </header>

      <section style={{background:palette.nav,color:"#fff",padding:"70px 24px"}}>
        <div style={{maxWidth:1200,margin:"0 auto"}}>
          <div style={{color:palette.accent2,fontSize:11,fontWeight:900,letterSpacing:2}}>OUR MENU</div>
          <h1 style={{fontSize:"clamp(52px,8vw,90px)",margin:"10px 0 8px",lineHeight:.95}}>
            {restaurant.name}
          </h1>
          <p style={{margin:0,color:"#dbe7f2",fontSize:18}}>Fresh menu items and current pricing.</p>
        </div>
      </section>

      <section style={{maxWidth:1200,margin:"0 auto",padding:"46px 24px 80px"}}>
        {grouped.length === 0 ? (
          <div style={{padding:30,background:palette.surface,borderRadius:14}}>No menu categories yet.</div>
        ) : (
          <div style={{display:"grid",gap:22}}>
            {grouped.map((category:any) => (
              <section key={category.id} style={{background:palette.surface,border:`1px solid ${palette.accent}33`,borderRadius:14,overflow:"hidden"}}>
                <div style={{background:palette.nav,color:"#fff",padding:"18px 22px",display:"flex",justifyContent:"space-between",gap:20}}>
                  <h2 style={{margin:0,fontSize:26}}>{category.name}</h2>
                  <span style={{color:palette.accent2,fontSize:11,fontWeight:900}}>{category.items.length} ITEMS</span>
                </div>

                <div>
                  {category.items.length === 0 ? (
                    <div style={{padding:22,color:"#6b7280"}}>No items in this category yet.</div>
                  ) : (
                    category.items.map((item:any) => (
                      <article key={item.id} style={{padding:"20px 22px",borderBottom:"1px solid #eee3d4"}}>
                        <div style={{display:"flex",gap:18,alignItems:"baseline"}}>
                          <strong style={{fontSize:18}}>{item.name}</strong>
                          {item.featured && <span style={{fontSize:9,fontWeight:900,color:"#b97800"}}>FEATURED</span>}
                          {item.price !== null && item.price !== undefined && (
                            <strong style={{marginLeft:"auto",color:palette.accent}}>${Number(item.price).toFixed(2)}</strong>
                          )}
                        </div>
                        {item.description && <p style={{margin:"8px 0 0",color:palette.muted,lineHeight:1.55}}>{item.description}</p>}
                      </article>
                    ))
                  )}
                </div>
              </section>
            ))}
          </div>
        )}
      </section>
    </main>
  );
}

export default function RestaurantFoodMenuPage() {
  const params = useParams<{ slug: string }>();
  const slug = Array.isArray(params?.slug) ? params.slug[0] : params?.slug;

  const [themeKey, setThemeKey] = useState<string | null>(null);
  const [checking, setChecking] = useState(true);

  useEffect(() => {
    if (!slug) return;

    async function checkTheme() {
      const { data } = await supabase
        .from("restaurants")
        .select("theme_key")
        .eq("slug", slug)
        .maybeSingle();

      setThemeKey(data?.theme_key || null);
      setChecking(false);
    }

    checkTheme();
  }, [slug]);

  if (!slug || checking) {
    return <main style={{minHeight:"100vh",background:"#08111f"}} />;
  }

  if (themeKey === "vi-pollos-custom") {
    return <ViPollosFoodMenuPage />;
  }

  return <StandardFoodMenuPage slug={slug} themeKey={themeKey} />;
}

